<?php require 'bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();q('UPDATE products SET active=0 WHERE id=?',[(int)post('id')]);flash('ปิดใช้งานสินค้าแล้ว ประวัติคำสั่งซื้อยังคงอยู่');go('admin/products.php');}admin_header('จัดการสินค้า');?><a class="button" href="product_add.php">+ เพิ่มสินค้า</a><form class="filters"><input name="q" placeholder="<?=e(t('ค้นหาสินค้า'))?>" value="<?=e($_GET['q']??'')?>"><button><?=e(t('ค้นหา'))?></button></form><div class="table-wrap"><table><tr><th><?=e(t('สินค้า'))?></th><th><?=e(t('ราคา'))?></th><th>สต็อก</th><th>สถานะ</th><th></th></tr><?php foreach(q('SELECT * FROM products WHERE name LIKE ? ORDER BY id DESC',['%'.($_GET['q']??'').'%']) as $p):?><tr><td><?=e(localized_name($p))?></td><td><?=money($p['price'])?></td><td><?=$p['stock']?></td><td><?=$p['active']?'ใช้งาน':'ปิดใช้งาน'?></td><td><a href="product_edit.php?id=<?=$p['id']?>"><?=e(t('แก้ไข'))?></a><form method="post" class="inline" data-confirm="ยืนยันปิดใช้งานสินค้า?"><?=csrf()?><input type="hidden" name="id" value="<?=$p['id']?>"><button class="text-button">ปิดใช้งาน</button></form></td></tr><?php endforeach ?></table></div><?php admin_footer();?>
